// AdGuardHomeFree aghbridge (P0-T2)
// Minimal status bridge for the module WebUI:
//
//	GET  /status  -> {"agh_running":bool,"impl":"kernelsu|apatch|unknown"}
//	GET|POST /exec -> P0 action whitelist: get_status only; else 403
//
// CORS: Access-Control-Allow-Origin * (+ OPTIONS preflight) so the KSU
// WebView can call this from a file:// page.
//
// Auth boundary (IMP-02): the P0 whitelist is read-only, so no token is
// needed for get_status. Write actions (P1-T2: start/stop/rollback/install)
// require the X-AGHF-Token header matching $AGHF_STATE/bridge_token
// (generated by customize.sh, mode 600); missing/invalid token -> 401.
// The token file is read internally only; its content is never returned
// or logged.
//
// Subcommand: aghbridge gen-hash <password> -> prints a bcrypt hash
// (used by customize.sh to fill __AGHF_ADMIN_HASH__; never logged).
package main

import (
	"crypto/subtle"
	"encoding/json"
	"flag"
	"fmt"
	"net"
	"net/http"
	"os"
	"path/filepath"
	"strings"

	"golang.org/x/crypto/bcrypt"
)

func main() {
	if len(os.Args) > 1 && os.Args[1] == "gen-hash" {
		if len(os.Args) != 3 {
			fmt.Fprintln(os.Stderr, "usage: aghbridge gen-hash <password>")
			os.Exit(2)
		}
		h, err := bcrypt.GenerateFromPassword([]byte(os.Args[2]), bcrypt.DefaultCost)
		if err != nil {
			fmt.Fprintln(os.Stderr, "gen-hash:", err)
			os.Exit(1)
		}
		fmt.Println(string(h))
		return
	}

	fs := flag.NewFlagSet("aghbridge", flag.ExitOnError)
	listen := fs.String("listen", "127.0.0.1:3001", "listen address")
	implFlag := fs.String("impl", "", "root implementation (kernelsu|apatch)")
	tokenFile := fs.String("token-file", defaultTokenFile(), "path to the 600-perm bridge auth token file")
	fs.Parse(os.Args[1:])

	impl := resolveImpl(*implFlag)
	srv := &server{impl: impl, tokenFile: *tokenFile}

	var ln net.Listener
	var err error
	if ln, err = net.Listen("tcp", *listen); err != nil {
		fmt.Fprintln(os.Stderr, "listen:", err)
		os.Exit(1)
	}
	fmt.Fprintf(os.Stderr, "aghbridge listening on %s impl=%s\n", *listen, impl)
	if err := http.Serve(ln, srv); err != nil {
		fmt.Fprintln(os.Stderr, "serve:", err)
	}
}

// resolveImpl: -impl flag > $AGHF_ROOT_IMPL > $APATCH / $KSU > unknown.
func resolveImpl(flagVal string) string {
	if flagVal != "" {
		return flagVal
	}
	if v := os.Getenv("AGHF_ROOT_IMPL"); v == "kernelsu" || v == "apatch" {
		return v
	}
	if os.Getenv("APATCH") != "" {
		return "apatch"
	}
	if os.Getenv("KSU") != "" {
		return "kernelsu"
	}
	return "unknown"
}

func aghRunning() bool {
	// Scan /proc/*/comm for the AdGuardHome process (no external deps).
	entries, err := os.ReadDir("/proc")
	if err != nil {
		return false
	}
	for _, e := range entries {
		if !e.IsDir() || !isNum(e.Name()) {
			continue
		}
		b, err := os.ReadFile(filepath.Join("/proc", e.Name(), "comm"))
		if err != nil {
			continue
		}
		if strings.TrimSpace(string(b)) == "AdGuardHome" {
			return true
		}
	}
	return false
}

func isNum(s string) bool {
	if s == "" {
		return false
	}
	for _, c := range s {
		if c < '0' || c > '9' {
			return false
		}
	}
	return true
}

type server struct {
	impl      string
	tokenFile string
}

// defaultTokenFile: $AGHF_STATE/bridge_token (set by service.sh env),
// falling back to the canonical data path.
func defaultTokenFile() string {
	if s := os.Getenv("AGHF_STATE"); s != "" {
		return filepath.Join(s, "bridge_token")
	}
	return "/data/adb/aghf/state/bridge_token"
}

// hasValidToken: constant-time compare of the X-AGHF-Token header against the
// token file content. Missing file or empty header -> false.
func (s *server) hasValidToken(r *http.Request) bool {
	got := r.Header.Get("X-AGHF-Token")
	if got == "" {
		return false
	}
	want, err := os.ReadFile(s.tokenFile)
	if err != nil {
		return false
	}
	want = []byte(strings.TrimSpace(string(want)))
	return subtle.ConstantTimeCompare([]byte(got), want) == 1
}

type statusResp struct {
	AghRunning bool   `json:"agh_running"`
	Impl       string `json:"impl"`
}

func (s *server) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Access-Control-Allow-Origin", "*")
	w.Header().Set("Access-Control-Allow-Methods", "GET, POST, OPTIONS")
	w.Header().Set("Access-Control-Allow-Headers", "Content-Type")
	if r.Method == http.MethodOptions {
		w.WriteHeader(http.StatusNoContent)
		return
	}

	switch r.URL.Path {
	case "/status":
		writeJSON(w, http.StatusOK, statusResp{aghRunning(), s.impl})

	case "/exec":
		action := extractAction(r)
		switch action {
		case "get_status":
			// P0 whitelist (read-only, no token needed; manual P0-T2 contract).
			writeJSON(w, http.StatusOK, statusResp{aghRunning(), s.impl})
		case "start", "stop", "install", "rollback", "reload":
			// Write actions land in P1-T2; gated by the token now (IMP-02).
			if !s.hasValidToken(r) {
				writeJSON(w, http.StatusUnauthorized, map[string]string{
					"error": "unauthorized (bridge token required for write actions)",
				})
				return
			}
			writeJSON(w, http.StatusNotImplemented, map[string]string{
				"error": "write action authorized but not implemented until P1-T2",
			})
		case "":
			writeJSON(w, http.StatusBadRequest, map[string]string{
				"error": "missing action (P0 whitelist: get_status)",
			})
		default:
			// Not in the whitelist: 403 regardless of token (manual P0-T2:
			// curl -X POST /exec -d '{"action":"rm_rf"}' -> 403).
			writeJSON(w, http.StatusForbidden, map[string]string{
				"error": "action not allowed",
			})
		}

	default:
		writeJSON(w, http.StatusNotFound, map[string]string{"error": "not found"})
	}
}

// extractAction: ?action= query param, or {"action":"..."} JSON body.
func extractAction(r *http.Request) string {
	if a := r.URL.Query().Get("action"); a != "" {
		return a
	}
	if r.Method == http.MethodPost {
		var body struct {
			Action string `json:"action"`
		}
		if err := json.NewDecoder(r.Body).Decode(&body); err == nil {
			return body.Action
		}
	}
	return ""
}

func writeJSON(w http.ResponseWriter, code int, v interface{}) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(code)
	json.NewEncoder(w).Encode(v)
}
